# Terms checked in the EBI Ontology Lookup Service (2026-11-12)
KNOWN_TERMS = {
    "NCBITaxon:10090": ("Mus musculus", "ncbitaxon"),
    "NCBITaxon:10116": ("Rattus norvegicus", "ncbitaxon"),
    "PATO:0000384": ("male", "pato"),
    "PATO:0000383": ("female", "pato"),
}


def _term(OntologyTerm, curie):
    label, ontology = KNOWN_TERMS[curie]
    obo = curie.replace(":", "_")
    term, _ = OntologyTerm.objects.get_or_create(
        curie=curie,
        defaults={
            "label": label,
            "ontology": ontology,
            "iri": f"http://purl.obolibrary.org/obo/{obo}",
        },
    )
    return term


def link_known_terms(apps, schema_editor):
    """Species and the sex of the existing animal profiles get their ontology term."""
    OntologyTerm = apps.get_model("mousetube_api", "OntologyTerm")
    Species = apps.get_model("mousetube_api", "Species")
    AnimalProfile = apps.get_model("mousetube_api", "AnimalProfile")
    for name, curie in (
        ("Mus musculus", "NCBITaxon:10090"),
        ("Rattus norvegicus", "NCBITaxon:10116"),
    ):
        Species.objects.filter(name__iexact=name, ontology_term__isnull=True).update(
            ontology_term=_term(OntologyTerm, curie)
        )
    for sex, curie in (("male", "PATO:0000384"), ("female", "PATO:0000383")):
        AnimalProfile.objects.filter(sex=sex, sex_term__isnull=True).update(
            sex_term=_term(OntologyTerm, curie)
        )


